import{A as e,E as t,d as n,f as r,l as i,p as a,s as o}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as s}from"./app-Bk8M88M6.js";var c=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/SQLServer/01_%E5%9F%BA%E7%A1%80%E7%AF%87/02_%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%E4%B8%8E%E8%A1%A8%E8%AE%BE%E8%AE%A1.html","title":"数据类型与表设计","lang":"zh-CN","frontmatter":{"title":"数据类型与表设计","order":2,"category":["数据库","SQLServer"],"tag":["SQL Server","数据类型","表设计","HIERARCHYID","时态表"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":9.02,"words":2705},"filePathRelative":"后端开发/数据库/SQLServer/01_基础篇/02_数据类型与表设计.md"}`),l={name:`02_数据类型与表设计.md`};function u(s,c,l,u,d,f){let p=e(`Mermaid`);return t(),i(`div`,null,[c[0]||=n(`<h1 id="数据类型与表设计" tabindex="-1"><a class="header-anchor" href="#数据类型与表设计"><span>数据类型与表设计</span></a></h1><blockquote><p><strong>选对数据类型，是表设计的地基。</strong> 一个 DECIMAL(18,2) 和 FLOAT 的选择，可能导致财务数据分毫之差；一个 NVARCHAR vs VARCHAR 的混淆，可能让中文乱码。本篇系统梳理 SQL Server 数据类型与表设计实战。</p></blockquote><hr><h2 id="一、数值类型" tabindex="-1"><a class="header-anchor" href="#一、数值类型"><span>一、数值类型</span></a></h2><h3 id="_1-1-精确数值类型" tabindex="-1"><a class="header-anchor" href="#_1-1-精确数值类型"><span>1.1 精确数值类型</span></a></h3><table><thead><tr><th>类型</th><th>范围</th><th>存储字节</th><th>典型场景</th></tr></thead><tbody><tr><td><code>TINYINT</code></td><td>0 ~ 255</td><td>1</td><td>状态码、排序号</td></tr><tr><td><code>SMALLINT</code></td><td>-32,768 ~ 32,767</td><td>2</td><td>年龄、数量</td></tr><tr><td><code>INT</code></td><td>-2^31 ~ 2^31-1</td><td>4</td><td>主键、计数</td></tr><tr><td><code>BIGINT</code></td><td>-2^63 ~ 2^63-1</td><td>8</td><td>大表主键、雪花 ID</td></tr><tr><td><code>DECIMAL(p,s)</code></td><td>-10^38+1 ~ 10^38-1</td><td>5~17</td><td>金额、精确计算</td></tr><tr><td><code>NUMERIC(p,s)</code></td><td>同 DECIMAL</td><td>5~17</td><td>同 DECIMAL</td></tr><tr><td><code>MONEY</code></td><td>±922万亿</td><td>8</td><td>货币（精度固定4位）</td></tr><tr><td><code>SMALLMONEY</code></td><td>±21万</td><td>4</td><td>小额货币</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 金额存储：DECIMAL vs MONEY vs FLOAT 的精度差异</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @d</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1234</span></span>
<span class="line"><span style="color:#ABB2BF;">       ,</span><span style="color:#E06C75;">@m</span><span style="color:#C678DD;"> MONEY</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1234</span></span>
<span class="line"><span style="color:#ABB2BF;">       ,</span><span style="color:#E06C75;">@f</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1234</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#E06C75;"> @d</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> DecimalVal      </span><span style="color:#7F848E;font-style:italic;">-- 100.1234（精确）</span></span>
<span class="line"><span style="color:#ABB2BF;">      ,</span><span style="color:#E06C75;">@m</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> MoneyVal        </span><span style="color:#7F848E;font-style:italic;">-- 100.1234（精确到4位小数）</span></span>
<span class="line"><span style="color:#ABB2BF;">      ,</span><span style="color:#E06C75;">@f</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> FloatVal;       </span><span style="color:#7F848E;font-style:italic;">-- 100.1234（可能存在浮点误差）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 浮点误差演示</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @a</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @b</span><span style="color:#C678DD;"> FLOAT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#E06C75;"> @a</span><span style="color:#ABB2BF;"> + </span><span style="color:#E06C75;">@b</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> Result;    </span><span style="color:#7F848E;font-style:italic;">-- 0.30000000000000004（不是精确的0.3！）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 正确做法：金额用 DECIMAL</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)) + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Result;  </span><span style="color:#7F848E;font-style:italic;">-- 0.30</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">金额绝不用 FLOAT</p><p>金融场景中，FLOAT 的浮点误差会在多次累加后放大，导致对账失败。<strong>永远用 DECIMAL 存储金额。</strong></p></div><h3 id="_1-2-近似数值类型" tabindex="-1"><a class="header-anchor" href="#_1-2-近似数值类型"><span>1.2 近似数值类型</span></a></h3><table><thead><tr><th>类型</th><th>范围</th><th>存储</th><th>场景</th></tr></thead><tbody><tr><td><code>FLOAT(n)</code></td><td>±1.79E+308</td><td>4 或 8</td><td>科学计算、统计</td></tr><tr><td><code>REAL</code></td><td>±3.40E+38</td><td>4</td><td>等同 FLOAT(24)</td></tr></tbody></table><hr><h2 id="二、字符类型" tabindex="-1"><a class="header-anchor" href="#二、字符类型"><span>二、字符类型</span></a></h2><table><thead><tr><th>类型</th><th>说明</th><th>存储</th><th>推荐</th></tr></thead><tbody><tr><td><code>CHAR(n)</code></td><td>定长非 Unicode</td><td>n 字节</td><td>仅纯 ASCII 定长</td></tr><tr><td><code>VARCHAR(n)</code></td><td>变长非 Unicode</td><td>实际长度+2</td><td>—</td></tr><tr><td><code>NCHAR(n)</code></td><td>定长 Unicode (UTF-16)</td><td>2n 字节</td><td>定长中文</td></tr><tr><td><code>NVARCHAR(n)</code></td><td>变长 Unicode (UTF-16)</td><td>2×实际+2</td><td><strong>推荐默认选择</strong></td></tr><tr><td><code>TEXT</code></td><td>大文本非 Unicode</td><td>最多 2GB</td><td>⚠️ <strong>已废弃</strong></td></tr><tr><td><code>NTEXT</code></td><td>大文本 Unicode</td><td>最多 1GB</td><td>⚠️ <strong>已废弃</strong></td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- VARCHAR vs NVARCHAR 的中文存储差异</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @v</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;你好&#39;</span><span style="color:#ABB2BF;">;   </span><span style="color:#7F848E;font-style:italic;">-- 乱码或截断（取决于排序规则）</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @n</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> N&#39;你好&#39;</span><span style="color:#ABB2BF;">; </span><span style="color:#7F848E;font-style:italic;">-- 正确存储</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- NVARCHAR(MAX) 替代 NTEXT</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Articles</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    ArticleId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Title </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,        </span><span style="color:#7F848E;font-style:italic;">-- 标题</span></span>
<span class="line"><span style="color:#ABB2BF;">    Content </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(MAX) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,       </span><span style="color:#7F848E;font-style:italic;">-- 正文（替代 NTEXT）</span></span>
<span class="line"><span style="color:#ABB2BF;">    Summary </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NULL</span><span style="color:#7F848E;font-style:italic;">            -- 摘要</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">NVARCHAR 是默认选择</p><p>在中文环境下，<strong>所有字符串列优先使用 NVARCHAR</strong>。VARCHAR 只在明确仅存 ASCII（如邮编、MD5哈希）时使用，可节省约一半存储空间。</p></div><hr><h2 id="三、日期时间类型" tabindex="-1"><a class="header-anchor" href="#三、日期时间类型"><span>三、日期时间类型</span></a></h2><table><thead><tr><th>类型</th><th>范围</th><th>精度</th><th>存储</th><th>推荐</th></tr></thead><tbody><tr><td><code>DATE</code></td><td>0001-01-01 ~ 9999-12-31</td><td>天</td><td>3</td><td>✅ 纯日期</td></tr><tr><td><code>TIME</code></td><td>00:00:00 ~ 23:59:59</td><td>100ns</td><td>3~5</td><td>✅ 纯时间</td></tr><tr><td><code>DATETIME</code></td><td>1753-01-01 ~ 9999-12-31</td><td>1/300秒</td><td>8</td><td>⚠️ 旧类型</td></tr><tr><td><code>DATETIME2(n)</code></td><td>0001-01-01 ~ 9999-12-31</td><td>100ns</td><td>6~8</td><td>✅ <strong>推荐</strong></td></tr><tr><td><code>DATETIMEOFFSET(n)</code></td><td>同 DATETIME2 + 时区</td><td>100ns</td><td>8~10</td><td>✅ 跨时区</td></tr><tr><td><code>SMALLDATETIME</code></td><td>1900-01-01 ~ 2079-06-06</td><td>分钟</td><td>4</td><td>⚠️ 旧类型</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- DATETIME2 vs DATETIME 的精度差异</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @dt</span><span style="color:#C678DD;"> DATETIME</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2024-06-15 14:30:25.123&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @dt2</span><span style="color:#C678DD;"> DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;2024-06-15 14:30:25.123&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#E06C75;"> @dt</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> OldDateTime       </span><span style="color:#7F848E;font-style:italic;">-- 2024-06-15 14:30:25.123（四舍五入到1/300秒）</span></span>
<span class="line"><span style="color:#ABB2BF;">      ,</span><span style="color:#E06C75;">@dt2</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> NewDateTime2;    </span><span style="color:#7F848E;font-style:italic;">-- 2024-06-15 14:30:25.123（精确到毫秒）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- DATETIMEOFFSET：带时区存储</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @dto</span><span style="color:#C678DD;"> DATETIMEOFFSET</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;2024-06-15 14:30:25.123 +08:00&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#E06C75;"> @dto</span><span style="color:#C678DD;"> AT</span><span style="color:#C678DD;"> TIME</span><span style="color:#C678DD;"> ZONE</span><span style="color:#98C379;"> &#39;UTC&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> UtcTime;  </span><span style="color:#7F848E;font-style:italic;">-- 转换为 UTC</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">新项目用 DATETIME2</p><p><code>DATETIME2</code> 比 <code>DATETIME</code> 范围更广、精度更高、存储更省。<strong>新项目一律用 DATETIME2</strong>，DATETIME 仅用于兼容旧系统。</p></div><hr><h2 id="四、特殊类型" tabindex="-1"><a class="header-anchor" href="#四、特殊类型"><span>四、特殊类型</span></a></h2><h3 id="_4-1-hierarchyid-—-层级数据" tabindex="-1"><a class="header-anchor" href="#_4-1-hierarchyid-—-层级数据"><span>4.1 HIERARCHYID — 层级数据</span></a></h3><p><code>HIERARCHYID</code> 是 SQL Server 专为树形结构设计的 CLR 类型，比传统的邻接表（ParentId）更高效。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 组织架构树</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Organization</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrgId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrgPath </span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,     </span><span style="color:#7F848E;font-style:italic;">-- 层级路径</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrgName </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrgLevel </span><span style="color:#C678DD;">AS</span><span style="color:#D19A66;"> OrgPath</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">GetLevel</span><span style="color:#ABB2BF;">()    </span><span style="color:#7F848E;font-style:italic;">-- 计算列：层级深度</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入数据：用 /1/、/1/1/、/1/2/ 表示层级</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Organization (OrgPath, OrgName) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;总公司&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/1/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;技术部&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/1/1/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;后端组&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/1/2/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;前端组&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/2/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;市场部&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#C678DD;">HIERARCHYID</span><span style="color:#ABB2BF;">::</span><span style="color:#56B6C2;">Parse</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/2/1/&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;品牌组&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询某节点的所有子孙</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Parent</span><span style="color:#C678DD;"> HIERARCHYID</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrgPath </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Organization </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> OrgName </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;技术部&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrgName, </span><span style="color:#D19A66;">OrgPath</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ToString</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> Path</span><span style="color:#ABB2BF;">, OrgLevel</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Organization</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> OrgPath</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">IsDescendantOf</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@Parent</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询直接子节点</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrgName, </span><span style="color:#D19A66;">OrgPath</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ToString</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> Path</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Organization</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> OrgPath</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">GetAncestor</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;"> @Parent</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-geometry-geography-—-空间数据" tabindex="-1"><a class="header-anchor" href="#_4-2-geometry-geography-—-空间数据"><span>4.2 GEOMETRY / GEOGRAPHY — 空间数据</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 存储和查询地理位置</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Stores</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    StoreId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    StoreName </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#C678DD;">    Location</span><span style="color:#C678DD;"> GEOGRAPHY</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#7F848E;font-style:italic;">  -- 经纬度</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入点（纬度 纬度, 经度）</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Stores (StoreName, </span><span style="color:#C678DD;">Location</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;北京旗舰店&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">GEOGRAPHY</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">Point</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9042</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4074</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&#39;上海分店&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">GEOGRAPHY</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">Point</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">31</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">2304</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">121</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4737</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查找 50km 内的门店</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Center</span><span style="color:#C678DD;"> GEOGRAPHY</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> GEOGRAPHY</span><span style="color:#ABB2BF;">::</span><span style="color:#C678DD;">Point</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">39</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9042</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">116</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">4074</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4326</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> StoreName,</span></span>
<span class="line"><span style="color:#D19A66;">       Location</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">STDistance</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@Center</span><span style="color:#ABB2BF;">) / </span><span style="color:#D19A66;">1000</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> DistanceKm</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Stores</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> Location</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">STDistance</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@Center</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#D19A66;"> 50000</span><span style="color:#7F848E;font-style:italic;">  -- 50km</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> DistanceKm;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-json-支持" tabindex="-1"><a class="header-anchor" href="#_4-3-json-支持"><span>4.3 JSON 支持</span></a></h3><p>SQL Server 2016+ 原生支持 JSON（通过 NVARCHAR 存储 + 内置函数解析）：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON 列存储灵活数据</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    ProductId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    ProductName </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Price </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Attributes </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(MAX)  </span><span style="color:#7F848E;font-style:italic;">-- JSON 格式属性</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Products </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;iPhone 15&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">6999</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">N&#39;{&quot;Color&quot;:&quot;深空黑&quot;,&quot;Storage&quot;:&quot;128GB&quot;,&quot;Weight&quot;:&quot;171g&quot;}&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;MacBook Pro&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">14999</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">N&#39;{&quot;Color&quot;:&quot;银色&quot;,&quot;CPU&quot;:&quot;M3&quot;,&quot;RAM&quot;:&quot;16GB&quot;}&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询 JSON 属性</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ProductName,</span></span>
<span class="line"><span style="color:#56B6C2;">       JSON_VALUE</span><span style="color:#ABB2BF;">(Attributes, </span><span style="color:#98C379;">&#39;$.Color&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Color,</span></span>
<span class="line"><span style="color:#56B6C2;">       JSON_VALUE</span><span style="color:#ABB2BF;">(Attributes, </span><span style="color:#98C379;">&#39;$.Storage&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Storage</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Products;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR JSON：将查询结果转为 JSON</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ProductId, ProductName, Price</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Products</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> Price </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 5000</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> JSON</span><span style="color:#C678DD;"> PATH</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、identity-vs-sequence" tabindex="-1"><a class="header-anchor" href="#五、identity-vs-sequence"><span>五、IDENTITY vs SEQUENCE</span></a></h2><h3 id="_5-1-identity-自增列" tabindex="-1"><a class="header-anchor" href="#_5-1-identity-自增列"><span>5.1 IDENTITY（自增列）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,  </span><span style="color:#7F848E;font-style:italic;">-- 从1开始，每次+1</span></span>
<span class="line"><span style="color:#ABB2BF;">    CustomerId </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate </span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#56B6C2;"> SYSDATETIME</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IDENTITY 无法手动插入（除非 SET IDENTITY_INSERT ON）</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> IDENTITY_INSERT Orders </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Orders (OrderId, CustomerId, OrderDate) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> IDENTITY_INSERT Orders </span><span style="color:#C678DD;">OFF</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-sequence-序列" tabindex="-1"><a class="header-anchor" href="#_5-2-sequence-序列"><span>5.2 SEQUENCE（序列）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SEQUENCE：更灵活的自增方案</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> SEQUENCE</span><span style="color:#61AFEF;"> seq_OrderNo</span></span>
<span class="line"><span style="color:#C678DD;">    AS</span><span style="color:#C678DD;"> BIGINT</span></span>
<span class="line"><span style="color:#C678DD;">    START</span><span style="color:#C678DD;"> WITH</span><span style="color:#D19A66;"> 100000</span></span>
<span class="line"><span style="color:#ABB2BF;">    INCREMENT </span><span style="color:#C678DD;">BY</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">    NO</span><span style="color:#ABB2BF;"> CACHE;  </span><span style="color:#7F848E;font-style:italic;">-- 或 CACHE 50 提高性能但可能跳号</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 在 INSERT 中使用</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Orders (OrderId, CustomerId, OrderDate)</span></span>
<span class="line"><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">NEXT</span><span style="color:#C678DD;"> VALUE</span><span style="color:#C678DD;"> FOR</span><span style="color:#ABB2BF;"> seq_OrderNo, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">SYSDATETIME</span><span style="color:#ABB2BF;">());</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SEQUENCE 优势：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 可跨表共享</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 可重置 (ALTER SEQUENCE ... RESTART)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 可定义 CACHE 减少锁争用</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 不绑定到特定列</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>特性</th><th>IDENTITY</th><th>SEQUENCE</th></tr></thead><tbody><tr><td>绑定列</td><td>是</td><td>否（独立对象）</td></tr><tr><td>跨表共享</td><td>❌</td><td>✅</td></tr><tr><td>手动获取下一个值</td><td>❌（需插入后取）</td><td>✅（NEXT VALUE FOR）</td></tr><tr><td>重置</td><td>DBCC CHECKIDENT</td><td>ALTER SEQUENCE RESTART</td></tr><tr><td>CACHE</td><td>❌</td><td>✅</td></tr><tr><td>事务回滚是否跳号</td><td>是（跳号）</td><td>是（跳号，CACHE 更明显）</td></tr></tbody></table><hr><h2 id="六、计算列与稀疏列" tabindex="-1"><a class="header-anchor" href="#六、计算列与稀疏列"><span>六、计算列与稀疏列</span></a></h2><h3 id="_6-1-计算列-computed-column" tabindex="-1"><a class="header-anchor" href="#_6-1-计算列-computed-column"><span>6.1 计算列（Computed Column）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> OrderItems</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    ItemId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    ProductName </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    Quantity </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    UnitPrice </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 持久化计算列：存入磁盘，可建索引</span></span>
<span class="line"><span style="color:#ABB2BF;">    LineTotal </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (Quantity * UnitPrice) </span><span style="color:#C678DD;">PERSISTED</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 非持久化计算列：每次查询时计算</span></span>
<span class="line"><span style="color:#ABB2BF;">    DiscountPrice </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (Quantity * UnitPrice * </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">9</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 持久化计算列可建索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> IX_OrderItems_LineTotal</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> OrderItems(LineTotal);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-稀疏列-sparse-column" tabindex="-1"><a class="header-anchor" href="#_6-2-稀疏列-sparse-column"><span>6.2 稀疏列（Sparse Column）</span></a></h3><p>当列中大部分值为 NULL 时，稀疏列可节省存储空间：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> ProductAttributes</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    ProductId </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    [Color]</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">) SPARSE </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,      </span><span style="color:#7F848E;font-style:italic;">-- 90% 的产品没有此属性</span></span>
<span class="line"><span style="color:#E06C75;">    [Size]</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;">) SPARSE </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,        </span><span style="color:#7F848E;font-style:italic;">-- 85% 没有</span></span>
<span class="line"><span style="color:#E06C75;">    [Weight]</span><span style="color:#C678DD;"> DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) SPARSE </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,     </span><span style="color:#7F848E;font-style:italic;">-- 80% 没有</span></span>
<span class="line"><span style="color:#E06C75;">    [Material]</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">) SPARSE </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,   </span><span style="color:#7F848E;font-style:italic;">-- 95% 没有</span></span>
<span class="line"><span style="color:#ABB2BF;">    ExtraData </span><span style="color:#C678DD;">XML</span><span style="color:#ABB2BF;"> COLUMN_SET </span><span style="color:#C678DD;">FOR</span><span style="color:#ABB2BF;"> ALL_SPARSE_COLUMNS  </span><span style="color:#7F848E;font-style:italic;">-- 列集：统一查询</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">稀疏列的代价</p><p>非 NULL 值的存储比普通列多 2~4 字节。只有当 NULL 比例 &gt; 40%（INT 类型）或 &gt; 60%（NVARCHAR 类型）时才划算。具体阈值参考 SQL Server 文档。</p></div><hr><h2 id="七、表分区-table-partitioning" tabindex="-1"><a class="header-anchor" href="#七、表分区-table-partitioning"><span>七、表分区（Table Partitioning）</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 创建分区函数：按日期范围分区</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> PARTITION</span><span style="color:#C678DD;"> FUNCTION</span><span style="color:#ABB2BF;"> pf_OrdersByDate(</span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">))</span></span>
<span class="line"><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> RANGE</span><span style="color:#ABB2BF;"> RIGHT </span><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;2023-01-01&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2025-01-01&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- RIGHT: 边界值属于右侧分区 → [..., 2023), [2023, 2024), [2024, 2025), [2025, ...)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 创建分区方案：映射到文件组</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> PARTITION</span><span style="color:#ABB2BF;"> SCHEME ps_OrdersByDate</span></span>
<span class="line"><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> PARTITION</span><span style="color:#ABB2BF;"> pf_OrdersByDate</span></span>
<span class="line"><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> (FG_History, FG_2023, FG_2024, FG_Current);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 创建分区表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId </span><span style="color:#C678DD;">BIGINT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderDate </span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    CustomerId </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Amount </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span></span>
<span class="line"><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> ps_OrdersByDate(OrderDate);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 4. 分区切换（最快的数据归档方式）</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> Orders SWITCH </span><span style="color:#C678DD;">PARTITION</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> Orders_Archive </span><span style="color:#C678DD;">PARTITION</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 瞬间完成，不移动数据，只修改元数据</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,48),a(p,{code:``}),c[1]||=n(`<hr><h2 id="八、时态表-system-versioned-temporal-tables" tabindex="-1"><a class="header-anchor" href="#八、时态表-system-versioned-temporal-tables"><span>八、时态表（System-Versioned Temporal Tables）</span></a></h2><p>SQL Server 2016+ 的时态表自动记录数据变更历史，无需手动维护历史表。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建时态表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Employees</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    EmployeeId </span><span style="color:#C678DD;">INT</span><span style="color:#56B6C2;"> IDENTITY</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Department </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Salary </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    ValidFrom </span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> ROW</span><span style="color:#C678DD;"> START</span><span style="color:#C678DD;"> HIDDEN</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    ValidTo </span><span style="color:#C678DD;">DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> ROW</span><span style="color:#C678DD;"> END</span><span style="color:#C678DD;"> HIDDEN</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    PERIOD</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> SYSTEM_TIME</span><span style="color:#ABB2BF;"> (ValidFrom, ValidTo)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SYSTEM_VERSIONING</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> (HISTORY_TABLE </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> dbo</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeesHistory</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 插入和修改数据</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> Employees (</span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Department, Salary) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;张三&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;IT&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">15000</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> Employees </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 18000</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> Name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> Employees </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> Department </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;管理&#39;</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> Name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询当前数据</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> EmployeeId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Department, Salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询某个时间点的数据</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> SYSTEM_TIME</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> OF </span><span style="color:#98C379;">&#39;2024-06-01T10:00:00&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询某段时间内的所有变更</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> SYSTEM_TIME</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;2024-12-31&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询所有历史版本</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> SYSTEM_TIME</span><span style="color:#ABB2BF;"> ALL;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,4),a(p,{code:`eJwrycxNzcnMS+VSAIKSzJKcVIVn07c9a2h8sXDFs6kbnvWue9o/49nsLUDBl9O3PN+1H6ywODW5JDM/T8E1tyAnvzI1tVjh6d7JTzt7gZrA8iBgZGBkomtgqGtoqmCl4OkX7BoUovB0z4InOzoVPEMUDE0NDAzQ1BrrGhkA1YYGuDiGuCq8mLbqxdYWhUdtkxQMLTAVm+kaIil+2bzi5fQVYMXP1y18PqENuzM9MotL8osqFZ72tT3t34TdtXUwdxB2bB3MFUhKwU4FACPfeOE=`}),c[2]||=o(`hr`,null,null,-1),c[3]||=o(`h2`,{id:`九、orchard-core-表结构设计`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#九、orchard-core-表结构设计`},[o(`span`,null,`九、Orchard Core 表结构设计`)])],-1),c[4]||=o(`p`,null,[o(`a`,{href:`https://github.com/OrchardCMS/OrchardCore`,target:`_blank`,rel:`noopener noreferrer`},`Orchard Core`),r(` 使用 YesSql ORM，采用文档-关系混合模式，所有表带 `),o(`code`,null,`Orchard_`),r(` 前缀。`)],-1),a(p,{code:`eJyNkE0OgjAQhfeeYsLeC7iVmOB/1LgfYQJNoDXtsDDg2hu4N96Nc1jAKIgkzK6v/d57U9KuwFBjMgI7rvLThCRDno/HKoOpkmyPHlOyI1/pACbg+FZEIY1TId0nbfZwOdOXjdAAW6WPzSq9HGFbeAFsFx/FsBYybEJe0HNZhraclshkuCVt01MsTEQdDxcZwZnvN2so7rfi8azLXpuVG1sNqLzGpK5Te5QBK2E/nYWSQ/gZIaea/qwbozG/4pG0scbvwBcOjY46`}),c[5]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Orchard Core 的核心表结构（简化）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Orchard_Framework_Document：文档存储表</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Type</span><span style="color:#ABB2BF;">, Content</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orchard_Framework_Document;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Orchard_Framework_ContentItemRecord：内容项表</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;"> Id, ContentItemId, ContentType, Latest, Published, ModifiedUtc</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orchard_Framework_ContentItemRecord;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Orchard_Framework_DataMigration：迁移版本跟踪</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> FeatureId, Class, </span><span style="color:#C678DD;">Version</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orchard_Framework_DataMigration</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> FeatureId;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Orchard Core 的设计理念</p><p>Orchard Core 的核心设计是 <strong>&quot;文档在关系型数据库上的投影&quot;</strong>：用 <code>Document</code> 表存储 JSON 文档（Content 字段），用 <code>ContentItemRecord</code> 管理版本和发布状态。这种设计让 CMS 内容建模极其灵活，同时保留了关系型数据库的查询能力。</p></div><hr><h2 id="十、面试技巧" tabindex="-1"><a class="header-anchor" href="#十、面试技巧"><span>十、面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频考点</p><ol><li><strong>DECIMAL vs FLOAT</strong>：金额场景必须用 DECIMAL，面试必问</li><li><strong>NVARCHAR vs VARCHAR</strong>：中文环境下默认 NVARCHAR，VARCHAR 省50%空间但只存 ASCII</li><li><strong>DATETIME2 vs DATETIME</strong>：新项目用 DATETIME2，范围更广精度更高</li><li><strong>IDENTITY vs SEQUENCE</strong>：SEQUENCE 跨表共享、可重置、可缓存，更灵活</li><li><strong>时态表</strong>：SQL Server 2016+ 特性，面试加分项，FOR SYSTEM_TIME 语法</li><li><strong>HIERARCHYID</strong>：树形结构专用类型，比邻接表高效</li><li><strong>表分区 vs 时态表</strong>：分区是性能优化，时态表是审计追踪，不要混淆</li></ol></div><div class="hint-container warning"><p class="hint-container-title">易错点</p><ul><li>&quot;MONEY 和 DECIMAL 一样&quot;——❌，MONEY 精度固定4位，运算可能截断；DECIMAL 可自定义精度</li><li>&quot;VARCHAR 能存中文&quot;——取决于排序规则（Collation），中文应使用 NVARCHAR + N 前缀</li><li>&quot;IDENTITY 保证不跳号&quot;——❌，事务回滚、实例重启都会跳号</li><li>&quot;稀疏列什么时候都能省空间&quot;——❌，非 NULL 值反而更耗空间</li></ul></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://learn.microsoft.com/en-us/sql/t-sql/data-types/data-types-transact-sql" target="_blank" rel="noopener noreferrer">Data Types (Transact-SQL)</a></li><li><a href="https://learn.microsoft.com/en-us/sql/t-sql/data-types/hierarchyid-data-type-method-reference" target="_blank" rel="noopener noreferrer">HIERARCHYID</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/tables/temporal-tables" target="_blank" rel="noopener noreferrer">Temporal Tables</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/json/json-data-sql-server" target="_blank" rel="noopener noreferrer">JSON Data</a></li><li><a href="https://github.com/OrchardCMS/OrchardCore" target="_blank" rel="noopener noreferrer">Orchard Core GitHub</a></li></ul>`,9)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};